//! Differential tests against the vanilla `ComponentSerialization.CODEC` / `getString()`.
//!
//! Fixtures are generated by `tests/fixtures/Golden.java` and `Translations.java` (see their headers)
//! from `corpus.txt` + `corpus_random.txt` (`gen_corpus.py`).

use mc_core::ident::Identifier;
use mc_nbt::{NbtAccounter, Tag, nbt_io};
use mc_text::{
    ChatFormatting, Component, Style, TextColor, TranslatableArg, Validators, legacy,
    set_validators,
};
use serde_json::Value;
use std::sync::Once;

const GOLDEN: &str = include_str!("../fixtures/golden.jsonl");
const TRANSLATIONS: &str = include_str!("../fixtures/translations.jsonl");
const MISC: &str = include_str!("../fixtures/misc.jsonl");
const NBT_TEXT: &str = include_str!("../fixtures/nbt_text.jsonl");

fn entity_type_exists(id: &Identifier) -> bool {
    id.namespace() == "minecraft" && matches!(id.path(), "pig" | "zombie")
}

fn item_exists(id: &Identifier) -> bool {
    id.namespace() == "minecraft" && matches!(id.path(), "stone" | "diamond_sword")
}

fn block_coordinates(s: &str) -> Result<(), String> {
    if s.is_empty() {
        Err("Incomplete (expected 1 coordinate)".into())
    } else {
        Ok(())
    }
}

/// The corpus only uses selectors/paths vanilla accepts; registries are limited to the ids it uses.
fn install_validators() {
    static ONCE: Once = Once::new();
    ONCE.call_once(|| {
        set_validators(Validators {
            entity_type_exists,
            item_exists,
            block_coordinates,
            ..Validators::default()
        });
    });
}

fn tag_from_hex(hex: &str) -> Tag {
    let bytes: Vec<u8> = (0..hex.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&hex[i..i + 2], 16).unwrap())
        .collect();
    nbt_io::read_unnamed_tag(&mut bytes.as_slice(), &mut NbtAccounter::unlimited_heap())
        .expect("fixture nbt")
}

/// Do two JSON values have the same keys *in the same order* everywhere?
fn same_key_order(a: &Value, b: &Value) -> bool {
    match (a, b) {
        (Value::Object(x), Value::Object(y)) => {
            x.len() == y.len()
                && x.iter()
                    .zip(y.iter())
                    .all(|((ka, va), (kb, vb))| ka == kb && same_key_order(va, vb))
        }
        (Value::Array(x), Value::Array(y)) => {
            x.len() == y.len() && x.iter().zip(y).all(|(p, q)| same_key_order(p, q))
        }
        _ => true,
    }
}

#[test]
fn component_codec_matches_vanilla() {
    install_validators();
    // MC_TEXT_GOLDEN=<file> runs a larger ad-hoc golden file (same format) instead of the committed one.
    let golden = std::env::var("MC_TEXT_GOLDEN")
        .ok()
        .map(|p| std::fs::read_to_string(p).unwrap());
    let golden = golden.as_deref().unwrap_or(GOLDEN);
    let mut ok_cases = 0;
    let mut err_cases = 0;
    let mut failures = Vec::new();
    for line in golden.lines() {
        let rec: Value = serde_json::from_str(line).unwrap();
        let src = rec["src"].as_str().unwrap();
        let kind = rec["kind"].as_str().unwrap();
        let input = rec["input"].as_str().unwrap();
        let expect_ok = rec["ok"].as_bool().unwrap();
        let decoded = if kind == "J" {
            Component::from_json(&serde_json::from_str::<Value>(input).unwrap())
        } else {
            Component::from_nbt(&tag_from_hex(input))
        };
        match (&decoded, expect_ok) {
            (Err(e), true) => {
                failures.push(format!("{src}\n   vanilla accepted, we rejected: {e}"));
                continue;
            }
            (Ok(c), false) => {
                failures.push(format!(
                    "{src}\n   vanilla rejected ({}), we accepted: {c}",
                    rec["err"].as_str().unwrap()
                ));
                continue;
            }
            (Err(_), false) => {
                err_cases += 1;
                continue;
            }
            (Ok(_), true) => ok_cases += 1,
        }
        let c = decoded.unwrap();

        match rec.get("json") {
            Some(expected) => {
                let expected: Value = serde_json::from_str(expected.as_str().unwrap()).unwrap();
                match c.to_json() {
                    Ok(got) if got == expected && same_key_order(&got, &expected) => {}
                    other => failures.push(format!(
                        "{src}\n   json expected {expected}\n   got      {other:?}"
                    )),
                }
            }
            None => {
                if c.to_json().is_ok() {
                    failures.push(format!(
                        "{src}\n   vanilla json encode fails ({}), ours succeeded",
                        rec["json_err"]
                    ));
                }
            }
        }
        match rec.get("nbt") {
            Some(expected) => {
                let expected = tag_from_hex(expected.as_str().unwrap());
                match c.to_nbt() {
                    Ok(got) if got == expected => {}
                    other => failures.push(format!(
                        "{src}\n   nbt expected {expected}\n   got      {other:?}"
                    )),
                }
            }
            None => {
                if c.to_nbt().is_ok() {
                    failures.push(format!(
                        "{src}\n   vanilla nbt encode fails ({}), ours succeeded",
                        rec["nbt_err"]
                    ));
                }
            }
        }
        check_visitors(&c, &rec, src, &mut failures);
        for (i, max) in [5usize, 20, 100, 1000].into_iter().enumerate() {
            let got = if kind == "J" {
                Component::from_json_flat_restricted(
                    &serde_json::from_str::<Value>(input).unwrap(),
                    max,
                )
                .is_ok()
            } else {
                Component::from_nbt_flat_restricted(&tag_from_hex(input), max).is_ok()
            };
            if Some(got) != rec["restricted"][i].as_bool() {
                failures.push(format!(
                    "{src}\n   flat restricted codec max={max}: ours accepted={got}, vanilla {}",
                    rec["restricted"][i]
                ));
            }
        }
        let expected_string = rec["string"].as_str().unwrap();
        if c.get_string() != expected_string {
            failures.push(format!(
                "{src}\n   getString expected {expected_string:?} got {:?}",
                c.get_string()
            ));
        }
    }
    assert!(
        failures.is_empty(),
        "{} failure(s) ({ok_cases} ok / {err_cases} rejected cases passed):\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert!(
        ok_cases > 300 && err_cases > 300,
        "corpus too small: {ok_cases} / {err_cases}"
    );
}

/// `Component.translatable(key, "<a1>", ..).getString()` for every en_us key (and renamed/removed ones).
#[test]
fn translatable_formatting_matches_vanilla() {
    let mut failures = Vec::new();
    let mut checked = 0;
    for line in TRANSLATIONS.lines() {
        let rec: Value = serde_json::from_str(line).unwrap();
        let key = rec["k"].as_str().unwrap();
        for (i, n) in [0usize, 2, 6].into_iter().enumerate() {
            let args = (1..=n)
                .map(|a| TranslatableArg::String(format!("<a{a}>")))
                .collect();
            let got = Component::translatable(key, args).get_string();
            let want = rec["o"][i].as_str().unwrap();
            checked += 1;
            if got != want {
                failures.push(format!("{key} (n={n}): expected {want:?} got {got:?}"));
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} failure(s) of {checked}:\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert!(checked > 20_000);
}

/// `getString(limit)`, `toFlatList()` and `contains()` against vanilla.
fn check_visitors(c: &Component, rec: &Value, src: &str, failures: &mut Vec<String>) {
    for (i, limit) in [0usize, 1, 2, 3, 5, 100].into_iter().enumerate() {
        if let Some(want) = rec["limits"][i].as_str() {
            let got = c.get_string_limit(limit);
            if got != want {
                failures.push(format!(
                    "{src}\n   getString({limit}) expected {want:?} got {got:?}"
                ));
            }
        }
    }
    let flat = c.to_flat_list();
    let got_flat: Result<Vec<Value>, _> = flat.iter().map(Component::to_json).collect();
    match (&rec["flat"], got_flat) {
        (Value::String(_), Err(_)) => {}
        (Value::Array(want), Ok(got)) if *want == got => {}
        (want, got) => failures.push(format!("{src}\n   toFlatList expected {want} got {got:?}")),
    }
    let want_contains = [
        Some(true),
        rec["contains"][1].as_bool(),
        rec["contains"][2].as_bool(),
    ];
    let got_contains = [
        Some(c.contains(c)),
        c.siblings().first().map(|s| c.contains(s)),
        Some(c.contains(&Component::literal("a"))),
    ];
    if want_contains != got_contains || rec["contains"][0].as_bool() != Some(true) {
        failures.push(format!(
            "{src}\n   contains expected {:?} got {got_contains:?}",
            rec["contains"]
        ));
    }
}

fn style_json(s: &Style) -> Value {
    s.to_json().expect("style encodes")
}

fn assert_style(what: &str, case: &Value, got: &Style, want: &Value, failures: &mut Vec<String>) {
    let got = style_json(got);
    if got != *want || !same_key_order(&got, want) {
        failures.push(format!(
            "{what}: a={} b={}\n   expected {want}\n   got      {got}",
            case["a"], case["b"]
        ));
    }
}

#[test]
fn style_color_and_legacy_helpers_match_vanilla() {
    let mut failures = Vec::new();
    let (mut styles, mut colors, mut strips) = (0, 0, 0);
    for line in MISC.lines() {
        let rec: Value = serde_json::from_str(line).unwrap();
        match rec["t"].as_str().unwrap() {
            "strip" => {
                strips += 1;
                let input = rec["in"].as_str().unwrap();
                if ChatFormatting::strip_formatting(input) != rec["out"].as_str().unwrap() {
                    failures.push(format!("strip_formatting({input:?})"));
                }
                if legacy::get_plain_text(&Component::literal(input))
                    != rec["plain"].as_str().unwrap()
                {
                    failures.push(format!("get_plain_text({input:?})"));
                }
            }
            "code" => {
                let c = rec["in"].as_str().unwrap().chars().next().unwrap();
                let got = ChatFormatting::get_by_code(c).map(|f| f.name().to_uppercase());
                if got.as_deref() != rec["out"].as_str() {
                    failures.push(format!("get_by_code({c:?}) = {got:?}, want {}", rec["out"]));
                }
            }
            "color" => {
                colors += 1;
                let input = rec["in"].as_str().unwrap();
                match (TextColor::parse_color(input), rec["ok"].as_bool().unwrap()) {
                    (Ok(c), true) => {
                        if c.serialize() != rec["ser"].as_str().unwrap()
                            || i64::from(c.value()) != rec["value"].as_i64().unwrap()
                        {
                            failures.push(format!(
                                "parse_color({input:?}) = {} / {}",
                                c.serialize(),
                                c.value()
                            ));
                        }
                    }
                    (Err(_), false) => {}
                    (got, want) => failures.push(format!(
                        "parse_color({input:?}) = {got:?}, vanilla ok={want}"
                    )),
                }
            }
            "style" => {
                styles += 1;
                let a = Style::from_json(&rec["a"]).unwrap();
                let b = Style::from_json(&rec["b"]).unwrap();
                assert_style(
                    "apply_to",
                    &rec,
                    &a.apply_to(&b),
                    &rec["apply_to"],
                    &mut failures,
                );
                if a.is_empty() != rec["empty"].as_bool().unwrap() {
                    failures.push(format!("is_empty a={}", rec["a"]));
                }
                for f in ChatFormatting::ALL {
                    let key = f.name().to_uppercase();
                    assert_style(
                        &format!("apply_format({key})"),
                        &rec,
                        &a.apply_format(f),
                        &rec["apply_format"][&key],
                        &mut failures,
                    );
                    assert_style(
                        &format!("apply_legacy_format({key})"),
                        &rec,
                        &a.apply_legacy_format(f),
                        &rec["apply_legacy_format"][&key],
                        &mut failures,
                    );
                }
                assert_style(
                    "apply_formats_1",
                    &rec,
                    &a.apply_formats(&[ChatFormatting::Red, ChatFormatting::Bold]),
                    &rec["apply_formats_1"],
                    &mut failures,
                );
                assert_style(
                    "apply_formats_2",
                    &rec,
                    &a.apply_formats(&[
                        ChatFormatting::Bold,
                        ChatFormatting::Reset,
                        ChatFormatting::Italic,
                    ]),
                    &rec["apply_formats_2"],
                    &mut failures,
                );
                assert_style(
                    "without_shadow",
                    &rec,
                    &a.without_shadow(),
                    &rec["without_shadow"],
                    &mut failures,
                );
                assert_style(
                    "with_bold_null",
                    &rec,
                    &a.with_bold(None),
                    &rec["with_bold_null"],
                    &mut failures,
                );
                assert_style(
                    "with_color_null",
                    &rec,
                    &a.with_color(None),
                    &rec["with_color_null"],
                    &mut failures,
                );
                assert_style(
                    "with_color_rgb",
                    &rec,
                    &a.with_color_rgb(0x123456),
                    &rec["with_color_0x123456"],
                    &mut failures,
                );
                assert_style(
                    "with_color_gold",
                    &rec,
                    &a.with_color_formatting(Some(ChatFormatting::Gold)),
                    &rec["with_color_gold"],
                    &mut failures,
                );
                assert_style(
                    "with_insertion",
                    &rec,
                    &a.with_insertion(Some("x".into())),
                    &rec["with_insertion_x"],
                    &mut failures,
                );
                assert_style(
                    "with_click_null",
                    &rec,
                    &a.with_click_event(None),
                    &rec["with_click_null"],
                    &mut failures,
                );
            }
            other => panic!("unknown record type {other}"),
        }
    }
    assert!(
        failures.is_empty(),
        "{} failure(s):\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert!(
        styles > 100 && colors > 20 && strips > 5,
        "fixture too small"
    );
}

/// `TextComponentTagVisitor` (sorted keys) for indentation {"", "  "} x styling {plain, rich}.
#[test]
fn nbt_text_component_visitor_matches_vanilla() {
    use mc_text::nbt_text::{Styling, TextComponentTagVisitor};
    let mut failures = Vec::new();
    let mut checked = 0;
    for line in NBT_TEXT.lines() {
        let rec: Value = serde_json::from_str(line).unwrap();
        let tag = tag_from_hex(rec["nbt"].as_str().unwrap());
        let mut i = 0;
        for indent in ["", "  "] {
            for styling in [Styling::Plain, Styling::Rich] {
                let got = TextComponentTagVisitor::with_options(indent, styling, true)
                    .visit(&tag)
                    .to_json()
                    .unwrap();
                checked += 1;
                if got != rec["out"][i] || !same_key_order(&got, &rec["out"][i]) {
                    failures.push(format!("{} (indent {indent:?}, {styling:?})", rec["src"]));
                }
                i += 1;
            }
        }
    }
    assert!(
        failures.is_empty(),
        "{} of {checked} mismatches:\n{}",
        failures.len(),
        failures.join("\n")
    );
    assert!(checked > 500);
}
